import{U as e,W as t,nt as n,t as r}from"./chunks/framework.BPwQCpO3.js";var i=JSON.parse(`{"title":"DeepSeek (BYOK Provider)","description":"","frontmatter":{"title":"DeepSeek (BYOK Provider)"},"headers":[],"relativePath":"providers/deepseek.md","filePath":"providers/deepseek.md"}`),a={name:`providers/deepseek.md`};function o(r,i,a,o,s,c){return n(),e(`div`,null,[...i[0]||=[t(`<h1 id="deepseek-mode-byok" tabindex="-1">DeepSeek (Mode BYOK) <a class="header-anchor" href="#deepseek-mode-byok" aria-label="Permalink to “DeepSeek (Mode BYOK)”">​</a></h1><p><strong>DeepSeek</strong> pilihan menarik untuk BYOK kalau kamu cari harga yang ramah di kantong dengan kualitas yang tetap layak untuk <em>roleplay</em> harian: daftar akun <strong>tanpa kartu kredit</strong>, model berbasis <em>top-up</em> (isi saldo sesuai kebutuhan), dan context window yang luas di model Flash terbarunya — hingga sekitar 1 juta token. Kalau kamu baru mengenal BYOK, baca dulu <a href="./../byok/">Pengenalan BYOK</a>.</p><div class="warning custom-block"><p class="custom-block-title">📅 Info penting 2026</p><p>Harga DeepSeek sempat <strong>naik drastis pada 16 Agustus 2026</strong> — kenaikan paling tajam justru di tarif <em>cache-hit</em>. Halaman ini mengajarkan <strong>cara</strong> yang benar, bukan angka harga. Cek halaman resmi <a href="https://api-docs.deepseek.com/quick_start/pricing" target="_blank" rel="noreferrer">harga DeepSeek API</a> dan <a href="https://www.deepseek.com/en/platform/" target="_blank" rel="noreferrer">platform DeepSeek</a> sebelum menetapkan budget.</p></div><hr><h2 id="membuat-api-key" tabindex="-1">Membuat API Key <a class="header-anchor" href="#membuat-api-key" aria-label="Permalink to “Membuat API Key”">​</a></h2><ol><li>Buat akun di <a href="https://platform.deepseek.com" target="_blank" rel="noreferrer">platform.deepseek.com</a> — pendaftaran <strong>tidak memerlukan kartu kredit</strong>.</li><li>Ikuti <em>profile wizard</em> saat pertama masuk, lalu buka bagian <strong>API Keys</strong> di sidebar.</li><li>Klik <strong>Create new API key</strong>, beri nama, lalu salin key yang ditampilkan.</li></ol><div class="danger custom-block"><p class="custom-block-title">🔒 Key only ditampilkan SEKALI</p><p>Setelah pembuatan, key hanya ditampilkan <strong>satu kali</strong>. Salin langsung ke tempat aman (password manager) sebelum menutup dialog. Yang sering kurang disadari: <em>duplikat sebuah kelemahan pemasangan API lain</em> — key yang bocor karena di-<em>paste</em> ke tempat publik bisa langsung dipakai orang lain memakai saldo top-up-mu. Jangan pernah menempelkan key ke chat, forum, atau <em>screenshot</em>.</p></div><hr><h2 id="mengaktifkan-deepseek-di-mikazuki-ai" tabindex="-1">Mengaktifkan DeepSeek di Mikazuki AI <a class="header-anchor" href="#mengaktifkan-deepseek-di-mikazuki-ai" aria-label="Permalink to “Mengaktifkan DeepSeek di Mikazuki AI”">​</a></h2><p>Ikuti alur BYOK standar dari panduan <a href="./../byok/instalasi.html">Instalasi &amp; Aktivasi</a>. Ringkasannya untuk DeepSeek:</p><ol><li>Buka <strong>Settings → Engine</strong>, pilih mode <strong>BYOK</strong>.</li><li>Pada pilihan provider, pilih <strong>Deepseek</strong>.</li><li>Tempel API key yang barusan kamu buat.</li><li>Klik tombol 🔍 <strong>fetch models</strong> — daftar model akan muncul otomatis dari key kamu.</li><li>Pilih model, atur <a href="./../byok/parameter-dasar.html">Parameter Dasar</a> — terutama <code>context_window</code> — lalu klik simpan.</li></ol><p>Worker Mikazuki memakai <strong>endpoint DeepSeek native</strong>, jadi tidak ada kolom <em>Base URL</em> untuk diisi — titik akhirnya fixed. API DeepSeek sendiri berformat <em>OpenAI-compatible</em> (base URL <code>https://api.deepseek.com</code>), jadi kalau perlu alternatif — misalnya provider native bermasalah — jalur <strong>OpenAI Compatible</strong> dengan Base URL tersebut juga bekerja dengan key DeepSeek yang sama.</p><h3 id="contoh-nama-model" tabindex="-1">Contoh nama model <a class="header-anchor" href="#contoh-nama-model" aria-label="Permalink to “Contoh nama model”">​</a></h3><p>Model yang kemungkinan besar kamu temui di daftar fetch models:</p><ul><li><strong><code>deepseek-flash</code></strong> — dilayani oleh DeepSeek-V4.1-Flash; nama legacy <code>deepseek-v4-flash</code> masih diterima.</li><li><strong><code>deepseek-v4-pro</code></strong> — kelas Pro untuk kualitas tulisan yang lebih berat.</li></ul><h3 id="prompt-berpikir-thinking" tabindex="-1">Prompt berpikir (thinking) <a class="header-anchor" href="#prompt-berpikir-thinking" aria-label="Permalink to “Prompt berpikir (thinking)”">​</a></h3><p>Model DeepSeek mendukung <em>prompt berpikir</em> melalui parameter <code>thinking: {&quot;type&quot;: &quot;enabled&quot;}</code> beserta <code>reasoning_effort</code>. Keduanya tidak ada di <a href="./../byok/parameter-dasar.html">Parameter Dasar</a> default, tapi bisa dilempar lewat <strong>Advanced Payload</strong>.</p><div class="warning custom-block"><p class="custom-block-title">⚠️ thinking itu mahal</p><p>Mengaktifkan <code>reasoning_effort</code> berisiko <strong>menaikkan biaya dan panjang respons</strong> secara signifikan — token &quot;berpikir&quot; tetap dihitung sebagai token output. Untuk <em>roleplay</em> santai, biasanya tidak perlu.</p></div><hr><h2 id="context-window-preset-1m" tabindex="-1">Context Window &amp; Preset 1M <a class="header-anchor" href="#context-window-preset-1m" aria-label="Permalink to “Context Window &amp; Preset 1M”">​</a></h2><p>Model Flash terbaru DeepSeek punya context window hingga sekitar <strong>1 juta token</strong> — pas dengan preset <code>1M</code> di Mikazuki:</p><ul><li><strong><code>deepseek-flash</code></strong> (Flash terbaru) → preset <code>1M</code> realistis untuk <em>roleplay</em> super panjang.</li><li><strong><code>deepseek-v4-pro</code></strong> atau model lain → kapasitas bisa berbeda; kalau ragu, mulai dari <code>128K</code>.</li></ul><p>Detail cara kerja <code>context_window</code>, <em>Reserved Output</em>, dan preset chip ada di <a href="./../byok/parameter-dasar.html">Parameter Dasar</a>.</p><div class="tip custom-block"><p class="custom-block-title">💡 Optimalkan 1M</p><p>Saat memakai preset <code>1M</code> di model Flash, kamu bisa menaikkan <code>max_tokens</code> agar jawaban punya ruang lebih besar — ingat bahwa <code>max_tokens</code> ikut dipotong dari context window.</p></div><hr><h2 id="free-tier-harga" tabindex="-1">Free Tier &amp; Harga <a class="header-anchor" href="#free-tier-harga" aria-label="Permalink to “Free Tier &amp; Harga”">​</a></h2><div class="warning custom-block"><p class="custom-block-title">Tidak ada free tier seperti Gemini</p><p>DeepSeek memakai model <strong>top-up balance (pre-paid)</strong>: kamu mengisi saldo terlebih dahulu lewat menu <em>top-up</em>, lalu pemakaian API memotong saldo itu. Sebelum isi saldo penuh, kamu biasanya tetap bisa menyelesaikan <em>setup</em> (membuat key, fetch models). Kalau saldo berakhir, API mengembalikan error <em>insufficient balance</em>.</p></div><h2 id="rate-limit-harga-per-jendela-waktu" tabindex="-1">Rate Limit &amp; Harga per Jendela Waktu <a class="header-anchor" href="#rate-limit-harga-per-jendela-waktu" aria-label="Permalink to “Rate Limit &amp; Harga per Jendela Waktu”">​</a></h2><ul><li><strong>Rate limit berbasis concurrency per akun</strong> — bukan RPM. Artinya yang dibatasi adalah <strong>jumlah request yang berjalan bersamaan</strong>, bukan jumlah request per menit. Nilai resminya: Flash sekitar <strong>2.500 koneksi bersamaan</strong> dan Pro sekitar <strong>500 koneksi bersamaan</strong> — jauh melampaui kebutuhan chat pribadi.</li></ul><div class="info custom-block"><p class="custom-block-title">Butuh lebih banyak?</p><p>Kalau kebutuhan concurrency-mu melampaui nilai default, DeepSeek menyediakan <strong>capacity expansion request</strong> yang bisa diajukan <strong>gratis</strong> dari platform. Untuk penggunaan pribadi, hampir tidak pernah perlu.</p></div><ul><li><strong>Harga dibedakan per juta token dengan split jendela waktu</strong>: tarif <strong>off-peak adalah setengah dari tarif peak</strong>. Jendela off-peak mengikuti jam-jam senggang global — jam persisnya bisa berubah, jadi cek langsung di halaman resmi, dan jangan kunci angka.</li></ul><p>Harga per model bisa berubah kapan saja (kenaikan besar 16 Agustus 2026 sudah disebut di atas), jadi tautan resmi <a href="https://api-docs.deepseek.com/quick_start/pricing" target="_blank" rel="noreferrer">harga DeepSeek API</a> adalah sumber satu-satunya yang layak untuk angka.</p><div class="warning custom-block"><p class="custom-block-title">⚠️ Jangan kunci angka</p><p>Kami sengaja tidak mencantumkan tabel angka harga di halaman ini — angkanya cepat basi, dan jendela peak/off-peak pun bisa bergeser. Tinjau <a href="https://api-docs.deepseek.com/quick_start/pricing" target="_blank" rel="noreferrer">halaman harga resmi</a> sebelum budgeting, dan monitor saldo top-up-mu di <a href="https://platform.deepseek.com" target="_blank" rel="noreferrer">Dashboard</a> agar tidak mengejutkanmu.</p></div><hr><h2 id="troubleshooting" tabindex="-1">Troubleshooting <a class="header-anchor" href="#troubleshooting" aria-label="Permalink to “Troubleshooting”">​</a></h2><details class="details custom-block"><summary>Error 401 — Insufficient Balance</summary><p>Saldo top-up-mu <strong>habis</strong>. Buka menu <em>top-up</em> di <a href="https://platform.deepseek.com" target="_blank" rel="noreferrer">Dashboard DeepSeek</a>, isi saldo, lalu ulangi request-nya. Kalau ternyata saldo masih ada tapi error tetap muncul, cek apakah key salah tempel / terpotong.</p></details><details class="details custom-block"><summary>Error 429 terus-menerus</summary><p>Rate limit DeepSeek berbasis <strong>concurrency</strong> — jumlah request yang berjalan bersamaan, bukan RPM. Kalau kena, tunggu request yang sedang berjalan <strong>selesai dulu</strong>, jangan spam retry (retry beruntun menambah request baru dan justru makan slot concurrency). Untuk kebutuhan lebih besar, ajukan <em>capacity expansion request</em> yang gratis.</p></details><details class="details custom-block"><summary>Nama model tidak valid</summary><p>Pakai nama persis dari daftar fetch models: <strong><code>deepseek-flash</code></strong> atau <strong><code>deepseek-v4-pro</code></strong>. Ketik manual mudah salah kapital atau salah format; kalau fetch gagal, isi kolom model secara <strong>manual</strong> dengan salah satu nama di atas.</p></details><details class="details custom-block"><summary>Jawaban terasa ringkih</summary><p><code>max_tokens</code> di <a href="./../byok/parameter-dasar.html">Parameter Dasar</a> mungkin terlalu kecil — model terpotong sebelum sempat menulis panjang. Naikkan nilainya, tapi ingat <code>max_tokens</code> juga dipotong dari context window sebagai <em>Reserved Output</em>, jadi jangan set berlebihan tanpa menaikkan <code>context_window</code>.</p></details><hr><h2 id="jelajahi-byok-lebih-lanjut" tabindex="-1">Jelajahi BYOK Lebih Lanjut <a class="header-anchor" href="#jelajahi-byok-lebih-lanjut" aria-label="Permalink to “Jelajahi BYOK Lebih Lanjut”">​</a></h2><ul><li><a href="./../byok/">Pengenalan BYOK</a> — konsep dasar dan cara kerjanya.</li><li><a href="./../byok/instalasi.html">Instalasi &amp; Aktivasi</a> — langkah menyalakan mode BYOK.</li><li><a href="./../byok/parameter-dasar.html">Parameter Dasar</a> — atur <code>max_tokens</code>, <code>context_window</code>, dan parameter kreativitas.</li><li><a href="./gemini.html">Google Gemini</a> — panduan padanan untuk provider Gemini.</li><li><a href="./systemai.html">System AI</a> — kalau kamu tidak ingin mengurus key dan pembayaran API sendiri.</li></ul>`,42)]])}var s=r(a,[[`render`,o]]);export{i as __pageData,s as default};